defmodule GPUI.Codegen do
  @moduledoc false

  alias RustQ.Rust

  @spec generated_native_element_schema() :: String.t()
  def generated_native_element_schema do
    components = GPUI.ComponentSpec.components()
    elements = GPUI.ComponentSpec.tags()
    style_specs = GPUI.ComponentSpec.style_specs()
    styles = GPUI.ComponentSpec.styles()
    events = GPUI.ComponentSpec.events()
    resource_specs = GPUI.ComponentSpec.resource_specs()
    resources = GPUI.ComponentSpec.resources()

    """
    // This file is generated by RustQ. Do not edit by hand.

    pub const GPUI_ELEMENT_TAGS: &[&str] = &[#{rust_string_list(elements)}];
    pub const GPUI_STYLE_ATTRS: &[&str] = &[#{rust_string_list(styles)}];
    pub const GPUI_EVENT_ATTRS: &[&str] = &[#{rust_string_list(events)}];
    pub const GPUI_RESOURCE_TYPES: &[&str] = &[#{rust_string_list(resources)}];

    #{generated_component_specs(components)}

    #{generated_style_struct(style_specs)}

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedElementTag {
        Div,
        Button,
        Input,
        Img,
        Text,
        Unknown,
    }

    pub fn decode_generated_element_tag(tag: &str) -> GeneratedElementTag {
        match tag {
    #{rust_match_arms(elements, "GeneratedElementTag")}
            _ => GeneratedElementTag::Unknown,
        }
    }

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedResourceType {
        Raster,
        ResourceRef,
        Unknown,
    }

    pub fn decode_generated_resource_type(resource_type: &str) -> GeneratedResourceType {
        match resource_type {
    #{rust_match_arms(resources, "GeneratedResourceType")}
            _ => GeneratedResourceType::Unknown,
        }
    }

    pub fn generated_event_attr_to_type(attr: &str) -> Option<&'static str> {
        match attr {
    #{rust_event_match_arms(components)}
            _ => None,
        }
    }

    pub fn generated_component_kind(tag: GeneratedElementTag) -> GeneratedComponentKind {
        match tag {
    #{rust_component_kind_arms(components)}
            GeneratedElementTag::Unknown => GeneratedComponentKind::Unknown,
        }
    }

    #{generated_decoded_resource_structs(resource_specs)}

    #{generated_decode_resource_functions(resource_specs)}

    #{generated_decoded_component_structs(components)}

    #{generated_decode_component_functions(components)}

    #{generated_apply_style_function(style_specs)}

    #{generated_apply_render_style_function(style_specs)}

    #{generated_event_applicators(components)}

    #{generated_primitive_render_contracts(components)}

    #{generated_render_dispatch()}
    """
  end

  @spec generated_host_commands() :: String.t()
  def generated_host_commands do
    """
    // This file is generated by RustQ. Do not edit by hand.

    #{generated_structs_and_decoders()}

    pub fn dispatch_host_command(op: &str, payload: &Term) -> Term {
        match op {
    #{generated_dispatch_arms()}
            _ => error_reply(format!("unsupported_op:{op}")),
        }
    }
    """
  end

  defp generated_dispatch_arms do
    GPUI.CommandSpec.host_commands()
    |> Enum.map_join("\n", fn {name, spec} ->
      handler = "handle_#{name}"
      decoder = "decode_#{name}"

      if Keyword.get(spec, :args, []) == [] do
        "        \"#{name}\" => #{handler}(),"
      else
        "        \"#{name}\" => match #{decoder}(payload) { Ok(command) => #{handler}(command), Err(reason) => error_reply(reason) },"
      end
    end)
  end

  defp generated_structs_and_decoders do
    GPUI.CommandSpec.host_commands()
    |> Enum.reject(fn {_name, spec} -> Keyword.get(spec, :args, []) == [] end)
    |> Enum.map_join("\n\n", fn {name, spec} ->
      struct_name = rust_struct_name(name)
      fields = Keyword.fetch!(spec, :args)

      field_defs =
        fields
        |> Enum.map_join("\n", fn {field, _type} -> "    pub #{field}: &'a Term," end)

      field_inits =
        fields
        |> Enum.map_join("\n", fn {field, _type} ->
          "        #{field}: required_payload(payload, \"#{field}\")?,"
        end)

      """
      pub struct #{struct_name}<'a> {
      #{field_defs}
      }

      pub fn decode_#{name}<'a>(payload: &'a Term) -> Result<#{struct_name}<'a>, String> {
          Ok(#{struct_name} {
      #{field_inits}
          })
      }
      """
    end)
  end

  defp generated_style_struct(style_specs) do
    Rust.struct(:StyleAttrs,
      derive: [:Clone, :Debug, :Default],
      attrs: [~s|cfg(feature = "real-gpui")|],
      fields:
        Enum.map(style_specs, fn spec ->
          Rust.field(spec.field, rust_style_type(spec.type))
        end)
    )
    |> Rust.to_fragment()
  end

  defp rust_style_type({:atom_eq, _expected}), do: "bool"
  defp rust_style_type(:atom_string), do: "Option<String>"
  defp rust_style_type(:rgb), do: "Option<u32>"
  defp rust_style_type(:px), do: "Option<f32>"
  defp rust_style_type(:radius), do: "Option<f32>"

  defp generated_decoded_resource_structs(resource_specs) do
    resource_specs
    |> Enum.map_join("\n\n", fn resource ->
      resource.name
      |> generated_resource_struct_name()
      |> Rust.struct(
        vis: :crate,
        derive: [:Clone, :Debug],
        attrs: [~s|cfg(feature = "real-gpui")|, "allow(dead_code)"],
        fields:
          Enum.map(resource.fields, fn {field, type} ->
            Rust.field(rust_field_name(field), rust_resource_type(type), vis: :crate)
          end)
      )
      |> Rust.to_fragment()
    end)
  end

  defp generated_decode_resource_functions(resource_specs) do
    resource_specs
    |> Enum.map_join("\n\n", fn resource ->
      struct_name = generated_resource_struct_name(resource.name)
      function_name = "decode_generated_#{resource.name}_resource"

      function_name
      |> Rust.fn_(
        vis: :crate,
        attrs: [~s|cfg(feature = "real-gpui")|, "allow(dead_code)"],
        args: [{:term, "Term"}],
        returns: "NifResult<#{struct_name}>",
        body: generated_decode_resource_body(resource, struct_name)
      )
      |> Rust.to_fragment()
    end)
  end

  defp generated_decode_resource_body(%{name: :raster}, struct_name) do
    """
        let env = term.get_env();
        Ok(#{struct_name} {
            width: term.map_get(Atom::from_bytes(env, b\"width\")?)?.decode::<u32>()?,
            height: term.map_get(Atom::from_bytes(env, b\"height\")?)?.decode::<u32>()?,
            format: term
                .map_get(Atom::from_bytes(env, b\"format\")?)?
                .atom_to_string()
                .unwrap_or_else(|_| \"rgba8\".to_string()),
            stride: optional_u32(term.map_get(Atom::from_bytes(env, b\"stride\")?).ok()),
            data: term
                .map_get(Atom::from_bytes(env, b\"data\")?)?
                .decode::<rustler::Binary>()?
                .as_slice()
                .to_vec(),
        })
    """
  end

  defp generated_decode_resource_body(%{name: :resource_ref}, struct_name) do
    """
        let env = term.get_env();
        Ok(#{struct_name} {
            id: term.map_get(Atom::from_bytes(env, b\"id\")?)?.decode::<String>()?,
            type_: term.map_get(Atom::from_bytes(env, b\"type\")?)?.atom_to_string().unwrap_or_default(),
        })
    """
  end

  defp rust_field_name(:type), do: :type_
  defp rust_field_name(field), do: field

  defp rust_resource_type(:u32), do: "u32"
  defp rust_resource_type(:string), do: "String"
  defp rust_resource_type(:binary), do: "Vec<u8>"

  defp rust_resource_type(:atom), do: "String"
  defp rust_resource_type({:option, :u32}), do: "Option<u32>"

  defp generated_resource_struct_name(name), do: "Generated#{Macro.camelize(to_string(name))}"

  defp generated_decoded_component_structs(components) do
    components
    |> Enum.map_join("\n\n", fn component ->
      component.tag
      |> generated_struct_name()
      |> Rust.struct(
        vis: :crate,
        derive: [:Clone, :Debug],
        attrs: [~s|cfg(feature = "real-gpui")|],
        fields: generated_struct_fields(component)
      )
      |> Rust.to_fragment()
    end)
  end

  defp generated_struct_fields(%{kind: :container}) do
    [
      Rust.field(:style, "StyleAttrs", vis: :crate),
      Rust.field(:children, "Vec<ElementNode>", vis: :crate),
      Rust.field(:click, "Option<String>", vis: :crate)
    ]
  end

  defp generated_struct_fields(%{kind: :input}) do
    [
      Rust.field(:style, "StyleAttrs", vis: :crate),
      Rust.field(:value, "String", vis: :crate),
      Rust.field(:placeholder, "Option<String>", vis: :crate),
      Rust.field(:change, "Option<String>", vis: :crate),
      Rust.field(:keydown, "Option<String>", vis: :crate),
      Rust.field(:keyup, "Option<String>", vis: :crate)
    ]
  end

  defp generated_struct_fields(%{kind: :image}) do
    [Rust.field(:raster, "RasterData", vis: :crate)]
  end

  defp generated_struct_fields(%{kind: :text}) do
    [Rust.field(:text, "String", vis: :crate)]
  end

  defp generated_decode_component_functions(components) do
    components
    |> Enum.map_join("\n\n", fn component ->
      struct_name = generated_struct_name(component.tag)
      function_name = "decode_generated_#{component.tag}"

      function_name
      |> Rust.fn_(
        vis: :crate,
        attrs: [~s|cfg(feature = "real-gpui")|],
        args: [{:term, "Term"}],
        returns: "NifResult<#{struct_name}>",
        body: generated_decode_body(component, struct_name)
      )
      |> Rust.to_fragment()
    end)
  end

  defp generated_decode_body(%{kind: :container, events: events}, struct_name) do
    click_attr = Keyword.get(events, :click, :"phx-click")

    """
          Ok(#{struct_name} {
              style: decode_style(term).unwrap_or_default(),
              children: decode_children(term).unwrap_or_default(),
              click: generated_string_attr(term, \"#{click_attr}\"),
          })
    """
  end

  defp generated_decode_body(%{kind: :input, events: events}, struct_name) do
    """
          Ok(#{struct_name} {
              style: decode_style(term).unwrap_or_default(),
              value: generated_string_attr(term, \"value\").unwrap_or_default(),
              placeholder: generated_string_attr(term, \"placeholder\"),
              change: generated_string_attr(term, \"#{Keyword.fetch!(events, :change)}\"),
              keydown: generated_string_attr(term, \"#{Keyword.fetch!(events, :keydown)}\"),
              keyup: generated_string_attr(term, \"#{Keyword.fetch!(events, :keyup)}\"),
          })
    """
  end

  defp generated_decode_body(%{kind: :image}, struct_name) do
    """
          Ok(#{struct_name} {
              raster: decode_raster(term)?,
          })
    """
  end

  defp generated_decode_body(%{kind: :text}, struct_name) do
    """
          Ok(#{struct_name} {
              text: decode_text_children(term).unwrap_or_default(),
          })
    """
  end

  defp generated_apply_render_style_function(style_specs) do
    Rust.fn_(:apply_generated_render_styles,
      vis: :crate,
      attrs: [~s|cfg(feature = "real-gpui")|],
      args: [{:element, "gpui::Div"}, {:style, "StyleAttrs"}],
      returns: "gpui::Div",
      body: """
          use gpui::{px, rgb, Styled};

          let mut element = element;
      #{rust_render_style_statements(style_specs)}
          element
      """
    )
    |> Rust.to_fragment()
  end

  defp rust_render_style_statements(style_specs) do
    style_specs
    |> Enum.reject(&is_nil(&1.render))
    |> Enum.map_join("\n", &rust_render_style_statement/1)
  end

  defp rust_render_style_statement(%{field: field, render: :flex_if_true}) do
    """
        if style.#{field} {
            element = element.flex();
        }
    """
  end

  defp rust_render_style_statement(%{field: field, render: {:enum_methods, values}}) do
    arms =
      values
      |> Enum.map_join("\n", fn {value, method} ->
        ~s|            Some("#{value}") => element = element.#{method}(),|
      end)

    """
        match style.#{field}.as_deref() {
    #{arms}
            _ => {}
        }
    """
  end

  defp rust_render_style_statement(%{field: field, render: {:option_method, method, :rgb}}) do
    """
        if let Some(value) = style.#{field} {
            element = element.#{method}(rgb(value));
        }
    """
  end

  defp rust_render_style_statement(%{field: field, render: {:option_method, method, :px}}) do
    """
        if let Some(value) = style.#{field} {
            element = element.#{method}(px(value));
        }
    """
  end

  defp generated_event_applicators(_components) do
    """
    #[cfg(feature = "real-gpui")]
    pub(crate) fn apply_generated_click_event(
        element: gpui::Div,
        event: Option<String>,
        runtime: ResourceArc<RuntimeResource>,
        window_id: u64,
    ) -> gpui::AnyElement {
        use gpui::{InteractiveElement, IntoElement, StatefulInteractiveElement};

        if let Some(event) = event {
            let runtime_for_click = runtime.clone();
            let element_id = format!("gpui-elixir-click-{window_id}-{event}");

            element.id(element_id).on_click(move |_event, _window, _cx| {
                let _ = push_event(
                    &runtime_for_click,
                    NativeEvent::Click { window_id, event: event.clone() },
                );
            }).into_any_element()
        } else {
            element.into_any_element()
        }
    }

    #[cfg(feature = "real-gpui")]
    pub(crate) fn apply_generated_input_events(
        element: gpui::Div,
        value: String,
        change: Option<String>,
        keydown: Option<String>,
        keyup: Option<String>,
        runtime: ResourceArc<RuntimeResource>,
        window_id: u64,
    ) -> gpui::AnyElement {
        use gpui::{InteractiveElement, IntoElement, StatefulInteractiveElement};

        let mut element = element.id(format!(
            "gpui-elixir-input-{window_id}-{}",
            change.clone().unwrap_or_default()
        ));

        if let Some(event) = change {
            let runtime_for_change = runtime.clone();
            let value_for_change = value.clone();
            element = element.on_click(move |_event, _window, _cx| {
                let _ = push_event(
                    &runtime_for_change,
                    NativeEvent::Input {
                        kind: "change".to_string(),
                        window_id,
                        event: event.clone(),
                        value: Some(value_for_change.clone()),
                    },
                );
            });
        }

        if let Some(event) = keydown {
            let runtime_for_keydown = runtime.clone();
            element = element.on_key_down(move |key_event, _window, _cx| {
                let value = key_event
                    .keystroke
                    .key_char
                    .clone()
                    .or_else(|| Some(key_event.keystroke.key.clone()));
                let _ = push_event(
                    &runtime_for_keydown,
                    NativeEvent::Input {
                        kind: "keydown".to_string(),
                        window_id,
                        event: event.clone(),
                        value,
                    },
                );
            });
        }

        if let Some(event) = keyup {
            let runtime_for_keyup = runtime.clone();
            element = element.on_key_up(move |key_event, _window, _cx| {
                let value = key_event
                    .keystroke
                    .key_char
                    .clone()
                    .or_else(|| Some(key_event.keystroke.key.clone()));
                let _ = push_event(
                    &runtime_for_keyup,
                    NativeEvent::Input {
                        kind: "keyup".to_string(),
                        window_id,
                        event: event.clone(),
                        value,
                    },
                );
            });
        }

        element.into_any_element()
    }
    """
  end

  defp generated_primitive_render_contracts(_components) do
    """
    #[cfg(feature = "real-gpui")]
    pub(crate) fn render_generated_text_component(text: String) -> gpui::AnyElement {
        render_generated_text_primitive(text)
    }

    #[cfg(feature = "real-gpui")]
    pub(crate) fn render_generated_image_component(raster: RasterData) -> gpui::AnyElement {
        render_generated_image_primitive(raster)
    }

    #[cfg(feature = "real-gpui")]
    pub(crate) fn render_generated_input_component(
        style: StyleAttrs,
        value: String,
        placeholder: Option<String>,
        change: Option<String>,
        keydown: Option<String>,
        keyup: Option<String>,
        runtime: ResourceArc<RuntimeResource>,
        window_id: u64,
    ) -> gpui::AnyElement {
        render_generated_input_primitive(style, value, placeholder, change, keydown, keyup, runtime, window_id)
    }

    #[cfg(feature = "real-gpui")]
    pub(crate) fn render_generated_container_component(
        style: StyleAttrs,
        children: Vec<ElementNode>,
        click: Option<String>,
        runtime: ResourceArc<RuntimeResource>,
        window_id: u64,
    ) -> gpui::AnyElement {
        render_generated_container_primitive(style, children, click, runtime, window_id)
    }
    """
  end

  defp generated_render_dispatch do
    Rust.fn_(:render_generated_element_node,
      vis: :crate,
      attrs: [~s|cfg(feature = "real-gpui")|],
      args: [
        {:node, "ElementNode"},
        {:runtime, "ResourceArc<RuntimeResource>"},
        {:window_id, "u64"}
      ],
      returns: "gpui::AnyElement",
      body: """
          match node {
              ElementNode::Text(text) => render_generated_text_component(text),
              ElementNode::Image(raster) => render_generated_image_component(raster),
              ElementNode::Input { style, value, placeholder, change, keydown, keyup } => {
                  render_generated_input_component(style, value, placeholder, change, keydown, keyup, runtime, window_id)
              }
              ElementNode::Div { style, children, click } => {
                  render_generated_container_component(style, children, click, runtime, window_id)
              }
          }
      """
    )
    |> Rust.to_fragment()
  end

  defp generated_apply_style_function(style_specs) do
    Rust.fn_(:apply_generated_style_attr,
      vis: :crate,
      attrs: [~s|cfg(feature = "real-gpui")|],
      args: [{:attrs, "&mut StyleAttrs"}, {:key, "&str"}, {:value, "Term"}],
      body: """
          match key {
      #{rust_style_apply_arms(style_specs)}
              _ => {}
          }
      """
    )
    |> Rust.to_fragment()
  end

  defp rust_style_apply_arms(style_specs) do
    Enum.map_join(style_specs, "\n", fn spec ->
      assignment = rust_style_assignment(spec.field, spec.type)
      ~s|            "#{spec.name}" => #{assignment},|
    end)
  end

  defp rust_style_assignment(field, {:atom_eq, expected}) do
    "attrs.#{field} = atom_eq(value, \"#{expected}\")"
  end

  defp rust_style_assignment(field, :atom_string), do: "attrs.#{field} = atom_string(value)"
  defp rust_style_assignment(field, :rgb), do: "attrs.#{field} = rgb_value(value)"
  defp rust_style_assignment(field, :px), do: "attrs.#{field} = px_value(value)"
  defp rust_style_assignment(field, :radius), do: "attrs.#{field} = radius_value(value)"

  defp generated_struct_name(tag), do: "Generated#{Macro.camelize(to_string(tag))}"

  defp generated_component_specs(components) do
    kinds = components |> Enum.map(& &1.kind) |> Enum.uniq()

    """
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum GeneratedComponentKind {
    #{Enum.map_join(kinds, "\n", &"    #{rust_variant(&1)},")}
        Unknown,
    }
    """
  end

  defp rust_event_match_arms(components) do
    components
    |> Enum.flat_map(& &1.events)
    |> Enum.uniq_by(fn {_event_type, attr} -> attr end)
    |> Enum.map_join("\n", fn {event_type, attr} ->
      ~s|            "#{attr}" => Some("#{event_type}"),|
    end)
  end

  defp rust_component_kind_arms(components) do
    components
    |> Enum.map_join("\n", fn component ->
      ~s|            GeneratedElementTag::#{rust_variant(component.tag)} => GeneratedComponentKind::#{rust_variant(component.kind)},|
    end)
  end

  defp rust_match_arms(values, enum_name) do
    values
    |> Enum.map_join("\n", fn value ->
      ~s|        "#{value}" => #{enum_name}::#{rust_variant(value)},|
    end)
  end

  defp rust_variant(value), do: value |> Atom.to_string() |> Macro.camelize()

  defp rust_string_list(values) do
    values
    |> Enum.map_join(", ", fn value -> ~s("#{value}") end)
  end

  defp rust_struct_name(name) do
    name
    |> Atom.to_string()
    |> Macro.camelize()
    |> Kernel.<>("Command")
  end
end
